def arxiv_search_papers(query, max_results=None, date_from=None, date_to=None, categories=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0520000" if __import__("os").path.isdir("./environment_mix/0520000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    # ---- usage/audit dynamics ----
    usage_name = "usage.json"
    usage = _load(usage_name)
    if not isinstance(usage, list):
        usage = []

    # ---- validate inputs ----
    if not isinstance(query, str) or not query.strip():
        rec = {
            "id": f"req_{int(t0.timestamp()*1000)}",
            "endpoint": "arxiv_search_papers",
            "timestamp": t0.isoformat() + "Z",
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": 0
        }
        usage.append(rec)
        _save(usage_name, usage)
        return _err("VALIDATION_ERROR", "Missing or empty query.")

    if max_results is None:
        max_results = 10
    if not isinstance(max_results, int):
        rec = {
            "id": f"req_{int(t0.timestamp()*1000)}",
            "endpoint": "arxiv_search_papers",
            "timestamp": t0.isoformat() + "Z",
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": 0
        }
        usage.append(rec)
        _save(usage_name, usage)
        return _err("VALIDATION_ERROR", "max_results must be an integer.")
    if max_results < 1:
        rec = {
            "id": f"req_{int(t0.timestamp()*1000)}",
            "endpoint": "arxiv_search_papers",
            "timestamp": t0.isoformat() + "Z",
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": 0
        }
        usage.append(rec)
        _save(usage_name, usage)
        return _err("VALIDATION_ERROR", "max_results must be >= 1.")

    def _parse_date(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be a string date in YYYY-MM-DD format.")
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date()
        except ValueError:
            return _err("VALIDATION_ERROR", f"Malformed {field}; expected YYYY-MM-DD.")
    d_from = _parse_date(date_from, "date_from")
    if isinstance(d_from, dict) and "error" in d_from:
        rec = {
            "id": f"req_{int(t0.timestamp()*1000)}",
            "endpoint": "arxiv_search_papers",
            "timestamp": t0.isoformat() + "Z",
            "status": "error",
            "error_code": d_from["error"]["code"],
            "latency_ms": 0
        }
        usage.append(rec)
        _save(usage_name, usage)
        return d_from

    d_to = _parse_date(date_to, "date_to")
    if isinstance(d_to, dict) and "error" in d_to:
        rec = {
            "id": f"req_{int(t0.timestamp()*1000)}",
            "endpoint": "arxiv_search_papers",
            "timestamp": t0.isoformat() + "Z",
            "status": "error",
            "error_code": d_to["error"]["code"],
            "latency_ms": 0
        }
        usage.append(rec)
        _save(usage_name, usage)
        return d_to

    if d_from and d_to and d_from > d_to:
        rec = {
            "id": f"req_{int(t0.timestamp()*1000)}",
            "endpoint": "arxiv_search_papers",
            "timestamp": t0.isoformat() + "Z",
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": 0
        }
        usage.append(rec)
        _save(usage_name, usage)
        return _err("VALIDATION_ERROR", "Invalid date range: date_from is after date_to.")

    if categories is not None:
        if not isinstance(categories, list) or any(not isinstance(c, str) for c in categories):
            rec = {
                "id": f"req_{int(t0.timestamp()*1000)}",
                "endpoint": "arxiv_search_papers",
                "timestamp": t0.isoformat() + "Z",
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": 0
            }
            usage.append(rec)
            _save(usage_name, usage)
            return _err("VALIDATION_ERROR", "categories must be an array of strings.")

    # ---- quota / rate limit (simple observable dynamics) ----
    # Rate limit: 120 calls per rolling minute across all callers (no explicit auth in schema).
    now = datetime.datetime.utcnow()
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in usage:
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            rt = datetime.datetime.fromisoformat(ts.replace("Z", ""))
        except Exception:
            continue
        if rt >= window_start:
            recent += 1
    if recent >= 120:
        rec = {
            "id": f"req_{int(t0.timestamp()*1000)}",
            "endpoint": "arxiv_search_papers",
            "timestamp": t0.isoformat() + "Z",
            "status": "error",
            "error_code": "RATE_LIMIT",
            "latency_ms": 0
        }
        usage.append(rec)
        _save(usage_name, usage)
        return _err("RATE_LIMIT", "Too many requests. Please retry later.")

    # Daily quota: 10,000 calls per UTC day across all callers.
    day = now.date()
    daily = 0
    for r in usage:
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            rt = datetime.datetime.fromisoformat(ts.replace("Z", ""))
        except Exception:
            continue
        if rt.date() == day:
            daily += 1
    if daily >= 10000:
        rec = {
            "id": f"req_{int(t0.timestamp()*1000)}",
            "endpoint": "arxiv_search_papers",
            "timestamp": t0.isoformat() + "Z",
            "status": "error",
            "error_code": "QUOTA_EXCEEDED",
            "latency_ms": 0
        }
        usage.append(rec)
        _save(usage_name, usage)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")

    # ---- read and filter papers ----
    papers = _load("papers.json")
    if not isinstance(papers, list):
        papers = []

    q = query.strip().lower()
    cat_set = set([c.strip() for c in categories]) if categories else None

    def _paper_published_date(p):
        pub = p.get("published")
        if not isinstance(pub, str):
            return None
        # Accept YYYY-MM-DD or ISO-like datetime; compare on date portion.
        pub_date_str = pub[:10]
        try:
            return datetime.datetime.strptime(pub_date_str, "%Y-%m-%d").date()
        except ValueError:
            return None

    results = []
    for p in papers:
        if not isinstance(p, dict):
            continue
        title = p.get("title") if isinstance(p.get("title"), str) else ""
        summary = p.get("summary") if isinstance(p.get("summary"), str) else ""
        authors = p.get("authors") if isinstance(p.get("authors"), list) else []
        categories_p = p.get("categories") if isinstance(p.get("categories"), list) else []
        authors_str = " ".join([a for a in authors if isinstance(a, str)])
        hay = (title + " " + summary + " " + authors_str).lower()

        if q and q not in hay:
            continue

        pub_d = _paper_published_date(p)
        if d_from and pub_d and pub_d < d_from:
            continue
        if d_to and pub_d and pub_d > d_to:
            continue
        # If published cannot be parsed and date filter is present, treat as non-match
        if (d_from or d_to) and pub_d is None:
            continue

        if cat_set is not None:
            cats_here = set([c for c in categories_p if isinstance(c, str)])
            if cats_here.isdisjoint(cat_set):
                continue

        results.append({
            "id": p.get("id"),
            "title": title,
            "authors": [a for a in authors if isinstance(a, str)],
            "categories": [c for c in categories_p if isinstance(c, str)],
            "published": p.get("published"),
            "summary": summary
        })

    # deterministic ordering: newest first by published when available, otherwise id
    def _sort_key(r):
        pub = r.get("published")
        pubd = None
        if isinstance(pub, str):
            try:
                pubd = datetime.datetime.fromisoformat(pub.replace("Z", ""))
            except Exception:
                try:
                    pubd = datetime.datetime.strptime(pub[:10], "%Y-%m-%d")
                except Exception:
                    pubd = None
        # None sorts last
        return (pubd is None, pubd if pubd is not None else datetime.datetime.min, str(r.get("id") or ""))
    results.sort(key=_sort_key, reverse=True)

    limited = results[:max_results]
    latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)

    rec = {
        "id": f"req_{int(t0.timestamp()*1000)}",
        "endpoint": "arxiv_search_papers",
        "timestamp": t0.isoformat() + "Z",
        "status": "ok",
        "latency_ms": latency_ms,
        "result_count": len(limited)
    }
    usage.append(rec)
    _save(usage_name, usage)

    return {
        "total_results": len(results),
        "returned": len(limited),
        "papers": limited
    }

_DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0520000" if __import__("os").path.isdir("./environment_mix/0520000") else "/app/database")
def arxiv_download_paper(paper_id, check_status=False):
    import json, os
    papers = json.load(open(os.path.join(_DB, 'papers.json'), encoding='utf-8'))
    if paper_id not in papers:
        return {'status': 'error', 'message': 'Paper ' + str(paper_id) + ' not found'}
    if check_status:
        return {'paper_id': paper_id, 'status': 'converted'}
    return {'paper_id': paper_id, 'status': 'downloaded',
            'resource_uri': 'arxiv://' + paper_id, 'title': papers[paper_id]['title']}

def arxiv_list_papers(limit=None, cursor=None, sort_by=None, sort_order=None, category=None, author=None, q=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0520000" if __import__("os").path.isdir("./environment_mix/0520000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    usage_name = "usage.json"
    usage = _load(usage_name)
    if not isinstance(usage, list):
        usage = []

    # ---- validate ----
    if limit is None:
        limit = 20
    if not isinstance(limit, int):
        rec = {
            "id": f"req_{int(t0.timestamp()*1000)}",
            "endpoint": "arxiv_list_papers",
            "timestamp": t0.isoformat() + "Z",
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": 0
        }
        usage.append(rec)
        _save(usage_name, usage)
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1:
        rec = {
            "id": f"req_{int(t0.timestamp()*1000)}",
            "endpoint": "arxiv_list_papers",
            "timestamp": t0.isoformat() + "Z",
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": 0
        }
        usage.append(rec)
        _save(usage_name, usage)
        return _err("VALIDATION_ERROR", "limit must be >= 1.")

    allowed_sort_by = {"published", "title", "id"}
    allowed_sort_order = {"asc", "desc"}

    if sort_by is None:
        sort_by = "published"
    if sort_order is None:
        sort_order = "desc"

    if sort_by not in allowed_sort_by:
        rec = {
            "id": f"req_{int(t0.timestamp()*1000)}",
            "endpoint": "arxiv_list_papers",
            "timestamp": t0.isoformat() + "Z",
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": 0
        }
        usage.append(rec)
        _save(usage_name, usage)
        return _err("VALIDATION_ERROR", "Invalid sort_by.", allowed=list(sorted(allowed_sort_by)))
    if sort_order not in allowed_sort_order:
        rec = {
            "id": f"req_{int(t0.timestamp()*1000)}",
            "endpoint": "arxiv_list_papers",
            "timestamp": t0.isoformat() + "Z",
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": 0
        }
        usage.append(rec)
        _save(usage_name, usage)
        return _err("VALIDATION_ERROR", "Invalid sort_order.", allowed=list(sorted(allowed_sort_order)))

    if cursor is not None and not isinstance(cursor, str):
        rec = {
            "id": f"req_{int(t0.timestamp()*1000)}",
            "endpoint": "arxiv_list_papers",
            "timestamp": t0.isoformat() + "Z",
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": 0
        }
        usage.append(rec)
        _save(usage_name, usage)
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    for fval, fname in [(category, "category"), (author, "author"), (q, "q")]:
        if fval is not None and not isinstance(fval, str):
            rec = {
                "id": f"req_{int(t0.timestamp()*1000)}",
                "endpoint": "arxiv_list_papers",
                "timestamp": t0.isoformat() + "Z",
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": 0
            }
            usage.append(rec)
            _save(usage_name, usage)
            return _err("VALIDATION_ERROR", f"{fname} must be a string.")

    # ---- rate/quota ----
    now = datetime.datetime.utcnow()
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in usage:
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            rt = datetime.datetime.fromisoformat(ts.replace("Z", ""))
        except Exception:
            continue
        if rt >= window_start:
            recent += 1
    if recent >= 120:
        rec = {
            "id": f"req_{int(t0.timestamp()*1000)}",
            "endpoint": "arxiv_list_papers",
            "timestamp": t0.isoformat() + "Z",
            "status": "error",
            "error_code": "RATE_LIMIT",
            "latency_ms": 0
        }
        usage.append(rec)
        _save(usage_name, usage)
        return _err("RATE_LIMIT", "Too many requests. Please retry later.")

    day = now.date()
    daily = 0
    for r in usage:
        ts = r.get("timestamp")
        if not isinstance(ts, str):
            continue
        try:
            rt = datetime.datetime.fromisoformat(ts.replace("Z", ""))
        except Exception:
            continue
        if rt.date() == day:
            daily += 1
    if daily >= 10000:
        rec = {
            "id": f"req_{int(t0.timestamp()*1000)}",
            "endpoint": "arxiv_list_papers",
            "timestamp": t0.isoformat() + "Z",
            "status": "error",
            "error_code": "QUOTA_EXCEEDED",
            "latency_ms": 0
        }
        usage.append(rec)
        _save(usage_name, usage)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")

    # ---- load papers ----
    papers = _load("papers.json")
    if not isinstance(papers, list):
        papers = []

    # ---- cursor decode ----
    start = 0
    if cursor:
        # Opaque but simple: "offset:<int>"
        if not cursor.startswith("offset:"):
            rec = {
                "id": f"req_{int(t0.timestamp()*1000)}",
                "endpoint": "arxiv_list_papers",
                "timestamp": t0.isoformat() + "Z",
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": 0
            }
            usage.append(rec)
            _save(usage_name, usage)
            return _err("VALIDATION_ERROR", "Unrecognized or expired cursor.")
        off = cursor.split(":", 1)[1]
        if not off.isdigit():
            rec = {
                "id": f"req_{int(t0.timestamp()*1000)}",
                "endpoint": "arxiv_list_papers",
                "timestamp": t0.isoformat() + "Z",
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": 0
            }
            usage.append(rec)
            _save(usage_name, usage)
            return _err("VALIDATION_ERROR", "Unrecognized or expired cursor.")
        start = int(off)

    # ---- filter ----
    q_l = (q or "").strip().lower()
    cat = category.strip() if isinstance(category, str) else None
    auth = author.strip() if isinstance(author, str) else None

    filtered = []
    for p in papers:
        if not isinstance(p, dict):
            continue
        if cat is not None:
            cats = p.get("categories")
            if not isinstance(cats, list) or cat not in [c for c in cats if isinstance(c, str)]:
                continue
        if auth is not None:
            aus = p.get("authors")
            if not isinstance(aus, list) or auth not in [a for a in aus if isinstance(a, str)]:
                continue
        if q_l:
            title = p.get("title") if isinstance(p.get("title"), str) else ""
            summary = p.get("summary") if isinstance(p.get("summary"), str) else ""
            if q_l not in (title + " " + summary).lower():
                continue
        filtered.append(p)

    # ---- sort ----
    def _norm_title(p):
        t = p.get("title")
        return t.lower() if isinstance(t, str) else ""
    def _norm_id(p):
        return str(p.get("id") or "")
    def _norm_published(p):
        pub = p.get("published")
        if not isinstance(pub, str):
            return None
        try:
            return datetime.datetime.fromisoformat(pub.replace("Z", ""))
        except Exception:
            try:
                return datetime.datetime.strptime(pub[:10], "%Y-%m-%d")
            except Exception:
                return None

    reverse = (sort_order == "desc")
    if sort_by == "title":
        filtered.sort(key=lambda p: (_norm_title(p), _norm_id(p)), reverse=reverse)
    elif sort_by == "id":
        filtered.sort(key=lambda p: _norm_id(p), reverse=reverse)
    else:  # published
        # None last regardless; then by id
        def _pub_key(p):
            d = _norm_published(p)
            return (d is None, d if d is not None else datetime.datetime.min, _norm_id(p))
        filtered.sort(key=_pub_key, reverse=reverse)

    total = len(filtered)
    if start < 0 or start > total:
        rec = {
            "id": f"req_{int(t0.timestamp()*1000)}",
            "endpoint": "arxiv_list_papers",
            "timestamp": t0.isoformat() + "Z",
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": 0
        }
        usage.append(rec)
        _save(usage_name, usage)
        return _err("VALIDATION_ERROR", "Unrecognized or expired cursor.")

    page = filtered[start:start + limit]
    next_cursor = None
    has_more = (start + limit) < total
    if has_more:
        next_cursor = f"offset:{start + limit}"

    # return metadata only
    out_rows = []
    for p in page:
        out_rows.append({
            "id": p.get("id"),
            "title": p.get("title"),
            "authors": p.get("authors") if isinstance(p.get("authors"), list) else [],
            "categories": p.get("categories") if isinstance(p.get("categories"), list) else [],
            "published": p.get("published"),
            "summary": p.get("summary")
        })

    latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
    rec = {
        "id": f"req_{int(t0.timestamp()*1000)}",
        "endpoint": "arxiv_list_papers",
        "timestamp": t0.isoformat() + "Z",
        "status": "ok",
        "latency_ms": latency_ms,
        "result_count": len(out_rows)
    }
    usage.append(rec)
    _save(usage_name, usage)

    return {
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "papers": out_rows
    }

_DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0520000" if __import__("os").path.isdir("./environment_mix/0520000") else "/app/database")
def arxiv_read_paper(paper_id):
    import json, os
    papers = json.load(open(os.path.join(_DB, 'papers.json'), encoding='utf-8'))
    if paper_id not in papers:
        return {'status': 'error', 'message': 'Paper ' + str(paper_id) + ' not found'}
    return {'paper_id': paper_id, 'title': papers[paper_id]['title'],
            'content': papers[paper_id]['markdown']}
